// Development host; Class queries, original Java componentType, workers and GC execute MASM.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public static class BoomClassQueryProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Pointer();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] args);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Query(ref Context c,IntPtr args,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr NewObject(IntPtr h,IntPtr layout,ref Context c);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr PoolCreate(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolRun(IntPtr p,IntPtr fn,IntPtr input,IntPtr output,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolDestroy(IntPtr p);
    static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Class query module load failed");return m;}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static int Reachable(IntPtr roots,uint n){var live=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!live.Add(p))continue;uint f=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((f&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&live.Count<1048576,"Malformed Class query graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return live.Count;}
    static void GC(IntPtr m,IntPtr h){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n);int live=Reachable(roots,n);Check(Fn<Collect>(m,"boom_heap_collect")(h,roots,n)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==live,"Class roots lost or temporary object leaked");}
    static IntPtr Ref(Entry entry,uint n){var c=new Context();ulong p=entry(ref c,new ulong[]{n});Check(p!=0&&c.Kind==0&&c.Depth==0,"Class reference VM entry failed");return new IntPtr(unchecked((long)p));}
    public static void Native(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),heap=IntPtr.Zero,args=IntPtr.Zero,copy=IntPtr.Zero,mirrorCopy=IntPtr.Zero;try{heap=Fn<Create>(m,"boom_heap_create")(1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1,"Class query heap binding failed");IntPtr pool=Fn<Pointer>(m,"boom_get_class_query_pool")(),mirrors=Marshal.ReadIntPtr(pool,16);Check(Marshal.ReadInt32(pool,4)==1&&Marshal.ReadInt32(pool,12)==1&&Marshal.ReadInt32(pool,8)==Marshal.ReadInt32(mirrors,12),"Class query nominal profile mismatch");var entry=Fn<Entry>(m,"boom_entry");var query=Fn<Query>(m,"boom_class_is_hidden");args=Marshal.AllocHGlobal(8);copy=Marshal.AllocHGlobal(32);mirrorCopy=Marshal.AllocHGlobal(64);var values=new IntPtr[16];for(uint i=0;i<16;i++)values[i]=Ref(entry,i);GC(m,heap);long baseline=Marshal.ReadInt64(heap,56);for(int i=0;i<8193;i++){Marshal.WriteIntPtr(args,values[i&15]);var c=new Context();Check(query(ref c,args,pool)==0&&c.Kind==0&&Marshal.ReadInt64(heap,56)==baseline,"Class query allocated or rejected a nominal definition");}
        Marshal.WriteIntPtr(args,IntPtr.Zero);var err=new Context{PC=17,Method=23};Check(query(ref err,args,pool)==0&&err.Kind==4&&err.PC==17&&err.Method==23,"Null Class query did not preserve NPE source");err=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(query(ref err,args,IntPtr.Zero)==0&&err.Kind==9&&err.PC==17&&err.Method==23&&err.Depth==3,"Pending Class query exception changed");
        byte[] data=new byte[32];Marshal.Copy(pool,data,0,32);Marshal.WriteIntPtr(args,values[0]);foreach(int off in new[]{0,4,8,12,16,24}){Marshal.Copy(data,0,copy,32);if(off<16)Marshal.WriteInt32(copy,off,off==8?0:2);else Marshal.WriteIntPtr(copy,off,off==24?new IntPtr(1):IntPtr.Zero);err=new Context{PC=17,Method=23};Check(query(ref err,args,copy)==0&&err.Kind==7&&err.PC==17&&err.Method==23,"Malformed query metadata accepted: "+off);}
        Marshal.Copy(data,0,copy,32);Marshal.WriteInt32(copy,8,65537);err=new Context();Check(query(ref err,args,copy)==0&&err.Kind==7,"Oversized Class profile accepted");Marshal.Copy(data,0,copy,32);Marshal.WriteInt32(copy,8,Marshal.ReadInt32(pool,8)+1);err=new Context();Check(query(ref err,args,copy)==0&&err.Kind==7,"Mismatched Class universe accepted");
        err=new Context();IntPtr fake=Fn<NewObject>(r,"boom_object_new")(heap,Marshal.ReadIntPtr(mirrors,32),ref err);Check(fake!=IntPtr.Zero&&err.Kind==0,"Forged mirror test setup failed");Marshal.WriteInt64(fake,Marshal.ReadInt64(values[0]));Marshal.WriteIntPtr(args,fake);err=new Context();Check(query(ref err,args,pool)==0&&err.Kind==7,"Unregistered mirror with valid type ID accepted");GC(m,heap);Check(Marshal.ReadInt64(heap,56)==baseline,"Forged mirror retained");Marshal.WriteIntPtr(args,values[0]);
        IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);Check(foreign!=IntPtr.Zero,"Foreign Class test heap failed");try{byte[] md=new byte[64];Marshal.Copy(mirrors,md,0,64);Marshal.Copy(md,0,mirrorCopy,64);Marshal.WriteIntPtr(mirrorCopy,48,foreign);Marshal.Copy(data,0,copy,32);Marshal.WriteIntPtr(copy,16,mirrorCopy);err=new Context();Check(query(ref err,args,copy)==0&&err.Kind==7,"Class mirror accepted outside the pool heap");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Foreign Class heap cleanup failed");}
        var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(heap,4096,0,267)!=IntPtr.Zero){}while(alloc(heap,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(heap,56);for(int i=0;i<8193;i++){Marshal.WriteIntPtr(args,values[i&15]);err=new Context();Check(query(ref err,args,pool)==0&&err.Kind==0&&Marshal.ReadInt64(heap,56)==full,"Full-heap Class query allocated or failed");}GC(m,heap);for(uint i=0;i<16;i++)Check(Ref(entry,i)==values[i],"Class mirror identity changed after GC");
    }finally{if(args!=IntPtr.Zero)Marshal.FreeHGlobal(args);if(copy!=IntPtr.Zero)Marshal.FreeHGlobal(copy);if(mirrorCopy!=IntPtr.Zero)Marshal.FreeHGlobal(mirrorCopy);if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Class heap cleanup failed");FreeLibrary(r);FreeLibrary(m);}}
    public static void Parallel(string dll,string runtime,int[] expected){const uint n=2049;IntPtr m=Open(dll),r=Open(runtime),heap=IntPtr.Zero,p=IntPtr.Zero,input=IntPtr.Zero,output=IntPtr.Zero;try{heap=Fn<Create>(m,"boom_heap_create")(16*1024*1024);Check(heap!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(heap)==1&&expected.Length==16,"Class worker heap or expectations invalid");p=Fn<PoolCreate>(r,"boom_pool_create")(8);Check(p!=IntPtr.Zero,"Class worker pool failed");input=Marshal.AllocHGlobal((int)n*128);output=Marshal.AllocHGlobal((int)n*32);for(int batch=0;batch<3;batch++){for(int i=0;i<n;i++)Marshal.WriteInt64(input,i*128,unchecked((long)((uint)(batch*n+i)*37U)));Check(Fn<PoolRun>(r,"boom_pool_run")(p,GetProcAddress(m,"boom_entry"),input,output,n)==0,"Class worker batch failed");for(int i=0;i<n;i++)Check(unchecked((int)Marshal.ReadInt64(output,i*32))==expected[unchecked((uint)(batch*n+i)*37U)&15]&&Marshal.ReadInt64(output,i*32+8)==0&&Marshal.ReadInt64(output,i*32+16)==0&&Marshal.ReadInt64(output,i*32+24)==0,"Class component or context crossed workers");GC(m,heap);}}
        finally{if(p!=IntPtr.Zero)Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(p)==0,"Class workers still active");if(input!=IntPtr.Zero)Marshal.FreeHGlobal(input);if(output!=IntPtr.Zero)Marshal.FreeHGlobal(output);if(heap!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(heap)!=0,"Class worker heap cleanup failed");FreeLibrary(r);FreeLibrary(m);}}
}
